#include <bits/stdc++.h>
using namespace std;

int m, children;
vector<long long> games;

// Subset DP: dp[mask] = (fewest bins for mask, smallest last-bin load with that many bins).
bool feasible(long long capacity) {
    vector<pair<int, long long>> dp(1 << m, {m + 1, 0});
    dp[0] = {1, 0};
    for (int mask = 1; mask < (1 << m); mask++) {
        pair<int, long long> best = {m + 1, 0};
        for (int bits = mask; bits; bits &= bits - 1) {
            int i = __builtin_ctz(bits);
            auto [rides, load] = dp[mask ^ (1 << i)];
            pair<int, long long> candidate =
                load + games[i] <= capacity ? make_pair(rides, load + games[i]) : make_pair(rides + 1, games[i]);
            best = min(best, candidate);
        }
        dp[mask] = best;
    }
    return dp[(1 << m) - 1].first <= children;
}

int main() {
    cin >> m >> children;
    games.resize(m);
    for (auto &g : games) cin >> g;
    long long total = accumulate(games.begin(), games.end(), 0LL);
    long long lo = max(*max_element(games.begin(), games.end()), (total + children - 1) / children), hi = total;
    while (lo < hi) {
        long long middle = (lo + hi) / 2;
        if (feasible(middle)) hi = middle;
        else lo = middle + 1;
    }
    cout << lo << '\n';
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }


    static int m, children;
    static long[] games;

    // Subset DP: (bins[mask], last[mask]) = fewest bins for mask, smallest last-bin load with that many bins.
    static boolean feasible(long capacity) {
        int full = 1 << m;
        int[] bins = new int[full];
        long[] last = new long[full];
        bins[0] = 1;
        for (int mask = 1; mask < full; mask++) {
            int bestBins = m + 1;
            long bestLoad = 0;
            for (int bits = mask; bits != 0; bits &= bits - 1) {
                int i = Integer.numberOfTrailingZeros(bits);
                int prev = mask ^ (1 << i);
                int r;
                long l;
                if (last[prev] + games[i] <= capacity) {
                    r = bins[prev];
                    l = last[prev] + games[i];
                } else {
                    r = bins[prev] + 1;
                    l = games[i];
                }
                if (r < bestBins || (r == bestBins && l < bestLoad)) {
                    bestBins = r;
                    bestLoad = l;
                }
            }
            bins[mask] = bestBins;
            last[mask] = bestLoad;
        }
        return bins[full - 1] <= children;
    }

    public static void main(String[] args) throws IOException {
        m = nextInt();
        children = nextInt();
        games = new long[m];
        long total = 0, biggest = 0;
        for (int i = 0; i < m; i++) {
            games[i] = nextLong();
            total += games[i];
            biggest = Math.max(biggest, games[i]);
        }
        long lo = Math.max(biggest, (total + children - 1) / children), hi = total;
        while (lo < hi) {
            long middle = (lo + hi) / 2;
            if (feasible(middle)) hi = middle;
            else lo = middle + 1;
        }
        System.out.println(lo);
    }
}

package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}


func main() {
	m, children := readInt(), readInt()
	games := make([]int, m)
	total, biggest := 0, 0
	for i := range games {
		games[i] = readInt()
		total += games[i]
		biggest = max(biggest, games[i])
	}
	full := 1 << m
	binsDP, lastDP := make([]int, full), make([]int, full)
	// Subset DP: (binsDP[mask], lastDP[mask]) = fewest bins for mask, smallest last-bin load with that many bins.
	feasible := func(capacity int) bool {
		binsDP[0], lastDP[0] = 1, 0
		for mask := 1; mask < full; mask++ {
			bestBins, bestLoad := m+1, 0
			for rest := mask; rest != 0; rest &= rest - 1 {
				i := bits.TrailingZeros(uint(rest))
				prev := mask ^ (1 << i)
				r, l := binsDP[prev]+1, games[i]
				if lastDP[prev]+games[i] <= capacity {
					r, l = binsDP[prev], lastDP[prev]+games[i]
				}
				if r < bestBins || (r == bestBins && l < bestLoad) {
					bestBins, bestLoad = r, l
				}
			}
			binsDP[mask], lastDP[mask] = bestBins, bestLoad
		}
		return binsDP[full-1] <= children
	}
	lo, hi := max(biggest, (total+children-1)/children), total
	for lo < hi {
		middle := (lo + hi) / 2
		if feasible(middle) {
			hi = middle
		} else {
			lo = middle + 1
		}
	}
	fmt.Println(lo)
}
